insert into public.recipes (id, name, cuisine, protein, minutes, effort, vibes, vegetarian, why, ingredients, steps) values
  (1, 'Cacio e Pepe', 'Italian', 'veg', 20, 2, array['comfort', 'cozy'], true, 'Finishing the pasta off the heat with starchy water keeps the cheese from clumping and turns it into a glossy sauce.', array['200g spaghetti', '1 cup finely grated pecorino', '1 tbsp black peppercorns, cracked', 'Salt', 'Pasta water'], array['Toast cracked pepper in a dry pan 1 minute.', 'Boil pasta in salted water, reserve 1 cup water, drain 2 minutes early.', 'Finish pasta in the pepper pan with a ladle of water.', 'Off the heat, toss in cheese with splashes of water until glossy.']),
  (2, 'Chicken Piccata', 'Italian', 'chicken', 30, 2, array['fresh'], false, 'A thin dusting of flour browns the cutlets and thickens the pan sauce at the same time.', array['2 chicken cutlets', 'Flour for dredging', '2 lemons', '2 tbsp capers', '1/2 cup chicken stock', 'Butter'], array['Season and flour the cutlets, sear 3 minutes per side, set aside.', 'Add stock, lemon juice and capers; reduce by half.', 'Swirl in butter, return chicken, spoon sauce over.']),
  (3, 'Chicken Tinga Tacos', 'Mexican', 'chicken', 35, 2, array['spicy', 'comfort'], false, 'Poaching thighs first keeps them juicy, and the smoky chipotle sauce clings to the shredded meat.', array['500g chicken thighs', '2 chipotles in adobo', '1 can crushed tomatoes', '1 onion', 'Corn tortillas', 'Lime and cilantro'], array['Simmer chicken in water with half the onion 20 minutes, shred.', 'Blend tomatoes, chipotles and remaining onion; simmer 10 minutes.', 'Fold in chicken, serve in warm tortillas with lime.']),
  (4, 'Black Bean Quesadillas', 'Mexican', 'veg', 15, 1, array['quick', 'comfort'], true, 'Mashing the beans makes a spreadable filling that holds together instead of sliding out.', array['1 can black beans', '4 flour tortillas', '1.5 cups shredded cheese', 'Cumin', 'Salsa'], array['Mash beans with cumin and a pinch of salt.', 'Fill tortillas with beans and cheese.', 'Griddle 2 minutes per side until crisp; serve with salsa.']),
  (5, 'Green Curry with Shrimp', 'Thai', 'seafood', 30, 2, array['spicy', 'cozy'], false, 'Frying the paste in coconut cream first wakes up its aromatics before the liquid goes in.', array['3 tbsp green curry paste', '1 can coconut milk', '400g shrimp', 'Thai basil', '1 zucchini', 'Fish sauce and lime'], array['Fry the paste in a spoon of coconut cream 1 minute.', 'Add remaining milk and zucchini, simmer 8 minutes.', 'Add shrimp until pink, finish with fish sauce, lime and basil.']),
  (6, 'Pad See Ew', 'Thai', 'beef', 25, 2, array['comfort'], false, 'A ripping-hot pan and a small batch give the noodles their smoky, charred edges.', array['Wide rice noodles', '200g sliced beef', 'Chinese broccoli', '2 eggs', 'Dark and light soy', 'Oyster sauce'], array['Sear beef in a very hot wok, push aside.', 'Scramble eggs, add greens and noodles.', 'Toss with soy and oyster sauce until charred at the edges.']),
  (7, 'Chana Masala', 'Indian', 'veg', 35, 2, array['cozy', 'spicy'], true, 'Blooming the spices in oil and mashing a few chickpeas builds a thick, deeply flavored sauce from pantry staples.', array['2 cans chickpeas', '1 onion', 'Ginger and garlic', '1 can tomatoes', '2 tbsp garam masala', 'Cilantro'], array['Brown the onion, add ginger, garlic and spices for 1 minute.', 'Add tomatoes and chickpeas, simmer 20 minutes.', 'Mash a few chickpeas to thicken; finish with cilantro.']),
  (8, 'Butter Chicken', 'Indian', 'chicken', 45, 3, array['comfort', 'cozy'], false, 'A yogurt marinade tenderizes the chicken, and charring it adds the smokiness a tandoor would.', array['600g chicken thighs', '1 cup yogurt', 'Garam masala', '1 can tomato purée', '1/2 cup cream', '4 tbsp butter'], array['Marinate chicken in yogurt and spices, ideally an hour.', 'Broil or sear until charred.', 'Simmer tomato, butter and spices 15 minutes; add cream and chicken.']),
  (9, 'Miso Salmon Rice Bowl', 'Japanese', 'seafood', 20, 1, array['quick', 'fresh'], false, 'Miso''s sugars caramelize fast under high heat, so a two-ingredient rub does the work of a long marinade.', array['2 salmon fillets', '2 tbsp white miso', '1 tbsp mirin', 'Cooked rice', 'Cucumber', 'Sesame seeds'], array['Rub salmon with miso and mirin.', 'Roast at 220°C for 10 minutes.', 'Serve over rice with sliced cucumber and sesame.']),
  (10, 'Chicken Katsu Curry', 'Japanese', 'chicken', 40, 3, array['comfort', 'cozy'], false, 'Pounding the chicken thin means it cooks in the time it takes the panko to turn golden.', array['2 chicken breasts', 'Panko, flour, egg', 'Curry roux block', '1 carrot, 1 onion', 'Rice'], array['Simmer carrot and onion in water, melt in roux.', 'Bread the pounded chicken: flour, egg, panko.', 'Shallow-fry 3 minutes per side; slice over rice and ladle sauce.']),
  (11, 'Smash Burgers', 'American', 'beef', 20, 1, array['comfort', 'quick'], false, 'Smashing loosely packed beef onto a very hot pan maximizes browned, crispy surface area.', array['400g ground beef', '4 potato buns', 'American cheese', 'Pickles', 'Onion', 'Burger sauce'], array['Roll beef into 4 loose balls.', 'Smash hard onto a screaming-hot pan, season, cook 2 minutes.', 'Flip, add cheese, stack on toasted buns.']),
  (12, 'Sheet-Pan Sausage and Veg', 'American', 'beef', 35, 1, array['quick', 'cozy'], false, 'Cutting everything to a similar size and roasting hot means one pan and one timer.', array['4 sausages', '2 potatoes', '1 red onion', 'Broccoli', 'Olive oil, mustard'], array['Chop everything into bite-size pieces, toss in oil.', 'Roast at 220°C for 25 minutes, flipping once.', 'Drizzle with mustard.']),
  (13, 'Lemony Chickpea Salad', 'Mediterranean', 'veg', 10, 1, array['fresh', 'quick'], true, 'Dressing the chickpeas while the vegetables are being chopped lets them soak up flavor.', array['1 can chickpeas', 'Cucumber', 'Cherry tomatoes', 'Red onion', 'Feta', 'Lemon and olive oil'], array['Chop the vegetables.', 'Toss with chickpeas, lemon and oil.', 'Crumble feta over the top.']),
  (14, 'Shakshuka', 'Mediterranean', 'egg', 25, 1, array['cozy', 'spicy'], true, 'Cooking the tomatoes down first gives the eggs a thick sauce to nestle in, so the whites set before the yolks harden.', array['4 eggs', '1 can tomatoes', '1 pepper', '1 onion', 'Cumin and paprika', 'Crusty bread'], array['Soften onion and pepper with the spices.', 'Add tomatoes, simmer 10 minutes.', 'Crack in eggs, cover, cook until whites set.']),
  (15, 'Egg Fried Rice', 'Chinese', 'egg', 15, 1, array['quick', 'comfort'], true, 'Day-old rice is drier, so the grains fry and separate instead of clumping.', array['3 cups day-old rice', '3 eggs', 'Frozen peas', 'Scallions', 'Soy sauce', 'Sesame oil'], array['Scramble the eggs in a hot wok, set aside.', 'Fry rice until it jumps and crackles.', 'Return eggs, add peas, soy and sesame oil.']),
  (16, 'Mapo Tofu', 'Chinese', 'tofu', 30, 2, array['spicy', 'comfort'], true, 'Frying the chile paste until the oil turns red builds the sauce''s deep flavor before the tofu goes in.', array['1 block soft tofu', '2 tbsp doubanjiang', '150g ground pork or mushrooms', 'Sichuan peppercorns', 'Scallions', 'Cornstarch slurry'], array['Fry the paste and pork until the oil turns red.', 'Add stock and tofu cubes, simmer 5 minutes.', 'Thicken with slurry, top with peppercorns and scallions.']),
  (17, 'Spaghetti Aglio e Olio', 'Italian', 'veg', 20, 1, array['quick', 'comfort'], true, 'Slowly cooking sliced garlic in plenty of oil flavors the whole sauce, and starchy pasta water turns the oil into a light coating.', array['200g spaghetti', '6 garlic cloves, thinly sliced', '1/3 cup olive oil', '1/2 tsp red pepper flakes', 'Chopped parsley', 'Salt'], array['Boil the spaghetti in well-salted water until just shy of done; reserve a cup of the water.', 'Cook the garlic in the oil over low heat until pale gold, 2 to 3 minutes. Add the pepper flakes.', 'Add the pasta and half a cup of pasta water; toss hard until glossy. Finish with parsley.']),
  (18, 'Sausage Ragù Rigatoni', 'Italian', 'beef', 40, 2, array['cozy', 'comfort'], false, 'Browning the sausage first builds a deep, savory base, so the sauce tastes slow-simmered in well under an hour.', array['300g rigatoni', '400g Italian sausage, casings removed', '1 onion, diced', '3 garlic cloves', '1 can crushed tomatoes', 'Parmesan', 'Olive oil'], array['Brown the sausage in oil, breaking it up, until crisp at the edges. Add onion and garlic and cook 5 minutes.', 'Add the tomatoes and simmer 20 minutes.', 'Boil the rigatoni, toss it in the sauce with a splash of pasta water, and top with Parmesan.']),
  (19, 'Huevos Rancheros', 'Mexican', 'egg', 25, 1, array['cozy', 'spicy'], true, 'Warming the tortillas and frying the eggs in the same skillet keeps this to one pan and one quick sauce.', array['4 corn tortillas', '4 eggs', '1 can refried beans', '1 cup salsa roja', '1 avocado', 'Crumbled cotija'], array['Warm the beans in a small pot and the salsa in another.', 'Toast the tortillas in an oiled skillet until pliable; set aside. Fry the eggs in the same pan.', 'Layer beans, an egg and salsa on each tortilla; top with avocado and cheese.']),
  (20, 'Carne Asada Tacos', 'Mexican', 'beef', 30, 2, array['comfort', 'quick'], false, 'A short citrus marinade tenderizes flank steak without turning it mushy, and slicing against the grain keeps every bite tender.', array['500g flank steak', '2 limes', '1 orange', '3 garlic cloves', '1 tsp cumin', 'Corn tortillas', 'Chopped onion and cilantro'], array['Marinate the steak in citrus juice, garlic, cumin and salt for at least 15 minutes.', 'Sear in a very hot pan 4 minutes per side. Rest 5 minutes.', 'Slice thinly against the grain and serve in warm tortillas with onion and cilantro.']),
  (21, 'Thai Basil Chicken', 'Thai', 'chicken', 20, 2, array['spicy', 'quick'], false, 'Very high heat and steady stirring give the ground chicken a caramelized crust before the basil wilts in at the end.', array['400g ground chicken', '4 garlic cloves', '2 to 3 Thai chilies', '2 tbsp soy sauce', '1 tbsp oyster sauce', '1 tsp sugar', '1 cup Thai basil leaves', 'Cooked rice'], array['Pound the garlic and chilies to a rough paste. Mix the soy, oyster sauce and sugar.', 'Fry the paste in hot oil 30 seconds, add the chicken, and cook until browned.', 'Add the sauce, then the basil off the heat. Serve over rice.']),
  (22, 'Coconut Mushroom Tom Kha', 'Thai', 'veg', 30, 1, array['cozy', 'fresh'], true, 'Bruising the lemongrass and simmering gently releases its aroma without splitting the coconut milk.', array['1 can coconut milk', '2 cups vegetable stock', '250g mushrooms, sliced', '2 lemongrass stalks', 'Thumb of ginger, sliced', '2 tbsp soy sauce', 'Lime juice', 'Chilies and cilantro'], array['Smash the lemongrass, then simmer it with the ginger and stock for 10 minutes.', 'Add the mushrooms and coconut milk; keep at a gentle simmer for 8 minutes.', 'Season with soy sauce and lime juice, then top with chilies and cilantro.']),
  (23, 'Palak Paneer', 'Indian', 'veg', 35, 2, array['cozy', 'comfort'], true, 'Blanching the spinach and blending it briefly keeps the sauce bright green instead of muddy.', array['500g spinach', '250g paneer, cubed', '1 onion', 'Ginger and garlic', '1 tsp cumin seeds', '1 tsp garam masala', '1/4 cup cream', '2 green chilies'], array['Blanch the spinach 1 minute, cool in cold water, then blend with the chilies.', 'Sizzle the cumin seeds, then cook the onion, ginger and garlic until soft.', 'Add the spinach purée and garam masala, simmer 5 minutes, then stir in the paneer and cream.']),
  (24, 'Coconut Red Lentil Dal', 'Indian', 'veg', 30, 1, array['cozy', 'comfort'], true, 'Red lentils fall apart quickly with no soaking, and a sizzling spiced oil poured on top adds a burst of flavor at the end.', array['1 cup red lentils', '3 cups water', '1 onion', '1 tomato', '1 tsp turmeric', '1 tbsp ghee or oil', '1 tsp cumin seeds', '3 garlic cloves', '2 dried chilies'], array['Simmer the lentils with the turmeric, half the onion and the tomato for 20 minutes until soft.', 'Mash lightly and season with salt.', 'Heat the ghee, fry the cumin, remaining onion, garlic and chilies until golden, and pour it over the dal.']),
  (25, 'Oyakodon', 'Japanese', 'chicken', 25, 2, array['comfort', 'quick'], false, 'Adding the egg in two stages leaves part of it fully set and part silky, which is the whole point of the dish.', array['2 chicken thighs, sliced', '1 onion, sliced', '3 eggs, lightly beaten', '1/2 cup dashi', '3 tbsp soy sauce', '2 tbsp mirin', '1 tbsp sugar', 'Cooked rice', 'Scallions'], array['Simmer dashi, soy, mirin and sugar; add the onion and chicken and cook 6 minutes.', 'Pour in two-thirds of the egg, cover for 1 minute, then add the rest.', 'Slide over rice while the egg is still soft and top with scallions.']),
  (26, 'Vegetable Yaki Udon', 'Japanese', 'veg', 20, 1, array['quick', 'comfort'], true, 'Loosening the noodles in hot water first keeps them from clumping and breaking apart in the pan.', array['2 packs fresh udon', 'Cabbage, shredded', '1 carrot, sliced', '4 shiitake or button mushrooms', '3 tbsp soy sauce', '1 tbsp mirin', '1 tsp sesame oil', 'Scallions'], array['Rinse the udon under hot water to loosen the strands.', 'Stir-fry the carrot, mushrooms and cabbage over high heat for 4 minutes.', 'Add the noodles, soy sauce and mirin and toss for 2 minutes. Finish with sesame oil and scallions.']),
  (27, 'Stovetop Mac and Cheese', 'American', 'veg', 30, 2, array['comfort', 'cozy'], true, 'Grating the cheese yourself and thickening the milk with a little flour keeps the sauce smooth instead of grainy.', array['250g elbow macaroni', '2 cups shredded sharp cheddar', '2 tbsp butter', '2 tbsp flour', '2 cups milk', '1/2 tsp mustard powder'], array['Cook the macaroni until just tender, drain.', 'Melt the butter, whisk in the flour and mustard for 1 minute, then slowly whisk in the milk until thick.', 'Off the heat, stir in the cheese until smooth, then fold in the pasta.']),
  (28, 'Weeknight Beef Chili', 'American', 'beef', 45, 2, array['cozy', 'comfort', 'spicy'], false, 'Blooming the chili powder and cumin in the fat before adding liquid deepens the flavor of the whole pot.', array['500g ground beef', '1 onion', '3 garlic cloves', '2 tbsp chili powder', '1 tbsp cumin', '1 can kidney beans', '1 can crushed tomatoes', '1 cup beef stock'], array['Brown the beef with the onion; drain excess fat.', 'Stir in garlic, chili powder and cumin for 1 minute.', 'Add tomatoes, beans and stock; simmer 30 minutes, stirring occasionally.']),
  (29, 'Lemon Herb Sheet-Pan Salmon', 'Mediterranean', 'seafood', 25, 1, array['fresh', 'quick'], false, 'Roasting the salmon on a bed of lemon slices protects the underside from drying out and perfumes the fish.', array['2 salmon fillets', '1 lemon, sliced', '1 zucchini, sliced', 'Cherry tomatoes', 'Olive oil', '1 tsp dried oregano', '2 garlic cloves'], array['Heat the oven to 220°C. Toss the zucchini and tomatoes with oil, garlic and oregano on a sheet pan.', 'Lay lemon slices down, set the salmon on top, and season.', 'Roast 12 minutes until the salmon flakes.']),
  (30, 'Chicken Shawarma Bowls', 'Mediterranean', 'chicken', 40, 2, array['fresh', 'comfort'], false, 'A yogurt and spice marinade tenderizes the chicken and helps it brown quickly under high heat.', array['500g chicken thighs', '1/2 cup yogurt', '1 tsp each cumin, coriander and paprika', '3 garlic cloves', '1 lemon', 'Cucumber and tomato', 'Pita and tahini'], array['Marinate the chicken in yogurt, spices, garlic and lemon juice for at least 15 minutes.', 'Roast at 230°C or sear in a hot pan until charred, about 15 minutes. Rest and slice.', 'Serve over chopped cucumber and tomato with pita and a drizzle of tahini.']),
  (31, 'Kung Pao Chicken', 'Chinese', 'chicken', 30, 2, array['spicy', 'comfort'], false, 'Coating the chicken in cornstarch keeps it juicy over high heat, and toasting the chilies first perfumes the oil.', array['500g chicken breast, cubed', '1 tbsp cornstarch', '6 dried chilies', '1/2 cup roasted peanuts', '3 scallions', '3 tbsp soy sauce', '1 tbsp rice vinegar', '1 tbsp sugar', 'Ginger and garlic'], array['Toss the chicken with cornstarch and a splash of soy sauce. Mix the remaining soy, vinegar and sugar.', 'Toast the chilies in hot oil for 15 seconds, then stir-fry the chicken until browned.', 'Add ginger, garlic, scallions and the sauce; toss with the peanuts.']),
  (32, 'Tomato and Egg Stir-Fry', 'Chinese', 'egg', 15, 1, array['quick', 'comfort'], true, 'Cooking the eggs until barely set and returning them at the end keeps them soft instead of rubbery.', array['4 eggs', '3 ripe tomatoes, cut in wedges', '2 scallions', '1 tsp sugar', '1 tbsp oil', 'Salt', 'Cooked rice'], array['Scramble the eggs in hot oil until just set and remove them.', 'Cook the tomatoes with the sugar and salt until they break down into a sauce.', 'Fold the eggs back in with the scallions and serve over rice.']),
  (33, 'Kimchi Fried Rice', 'Korean', 'egg', 20, 1, array['spicy', 'quick', 'comfort'], false, 'Frying the kimchi first concentrates its tang and heat before the rice goes in.', array['2 cups day-old rice', '1 cup chopped kimchi', '2 scallions', '1 tbsp gochujang', '1 tsp sesame oil', '2 fried eggs', 'Sesame seeds'], array['Fry the kimchi in oil for 3 minutes until slightly caramelized.', 'Add the rice and gochujang and stir-fry until the grains are hot and coated.', 'Finish with sesame oil and scallions and top with fried eggs.']),
  (34, 'Bulgogi Beef Bowls', 'Korean', 'beef', 35, 2, array['comfort'], false, 'Grated pear in the marinade tenderizes the thin-sliced beef and adds a light sweetness.', array['400g thinly sliced sirloin or ribeye', '1 Asian pear, grated', '4 tbsp soy sauce', '1 tbsp sugar', '1 tbsp sesame oil', '4 garlic cloves', 'Scallions', 'Cooked rice'], array['Mix the pear, soy sauce, sugar, sesame oil and garlic; marinate the beef at least 20 minutes.', 'Sear the beef in a very hot pan in small batches so it browns instead of steaming.', 'Serve over rice with scallions.']),
  (35, 'Soft Tofu Stew', 'Korean', 'tofu', 30, 2, array['spicy', 'cozy'], true, 'Blooming the chili flakes in oil makes a deeply red, aromatic base for the delicate tofu.', array['1 tube silken tofu', '1 zucchini, sliced', '4 mushrooms', '2 tbsp gochugaru', '2 cups vegetable stock', '2 garlic cloves', '1 egg', 'Scallions', '1 tsp sesame oil'], array['Cook the garlic and gochugaru in sesame oil for 30 seconds.', 'Add the stock, zucchini and mushrooms and simmer 8 minutes.', 'Spoon in the tofu in big chunks, crack in the egg, and simmer 3 minutes. Top with scallions.']),
  (36, 'Gochujang Chicken Thighs', 'Korean', 'chicken', 35, 1, array['spicy', 'comfort'], false, 'Gochujang''s sugars caramelize in the oven, giving a sticky glaze without any frying.', array['600g chicken thighs', '3 tbsp gochujang', '1 tbsp soy sauce', '1 tbsp honey', '1 tbsp sesame oil', '3 garlic cloves', 'Sesame seeds', 'Cooked rice'], array['Whisk the gochujang, soy sauce, honey, sesame oil and garlic; coat the chicken.', 'Roast at 220°C for 25 minutes, basting once, until charred at the edges.', 'Scatter with sesame seeds and serve with rice.']),
  (37, 'Croque Monsieur', 'French', 'beef', 30, 2, array['comfort', 'cozy'], false, 'Spreading a quick béchamel and Gruyère on top before broiling gives the sandwich a bubbling, browned crust.', array['4 slices sandwich bread', '4 slices ham', '1 cup grated Gruyère', '1 tbsp butter', '1 tbsp flour', '1/2 cup milk', 'Dijon mustard'], array['Melt the butter, whisk in the flour, then the milk, and simmer until thick. Stir in half the cheese.', 'Spread mustard on the bread and build sandwiches with ham and remaining cheese.', 'Top with the sauce and broil 4 minutes until golden and bubbling.']),
  (38, 'Ratatouille', 'French', 'veg', 50, 2, array['fresh', 'cozy'], true, 'Cooking each vegetable separately before combining them keeps distinct textures instead of one uniform mush.', array['1 eggplant', '2 zucchini', '1 bell pepper', '1 onion', '4 tomatoes', '3 garlic cloves', 'Olive oil', 'Fresh thyme'], array['Cut everything into similar chunks.', 'Sauté the eggplant, zucchini and pepper in batches in olive oil until golden; set aside.', 'Cook the onion and garlic, add the tomatoes and thyme, then return all the vegetables and simmer 15 minutes.']),
  (39, 'Steak Frites', 'French', 'beef', 40, 3, array['comfort'], false, 'Resting the steak and building a pan sauce from the browned bits captures flavor that would otherwise be lost.', array['2 sirloin steaks', '3 potatoes, cut into fries', '2 tbsp butter', '1 shallot, minced', '1/4 cup red wine or stock', 'Fresh thyme', 'Oil, salt'], array['Toss the fries with oil and roast at 230°C for 30 minutes, turning once.', 'Sear the seasoned steaks 3 to 4 minutes per side with butter and thyme. Rest 5 minutes.', 'Cook the shallot in the pan, add the wine, reduce by half, and swirl in butter to finish.']),
  (40, 'Mussels in White Wine', 'French', 'seafood', 25, 1, array['quick', 'fresh'], false, 'Covering the pot lets the mussels steam open in their own liquor, and they are done the moment they open.', array['1 kg mussels, scrubbed', '1 shallot', '3 garlic cloves', '1 cup dry white wine', '2 tbsp butter', 'Chopped parsley', 'Crusty bread'], array['Soften the shallot and garlic in butter, add the wine, and bring to a boil.', 'Add the mussels, cover, and steam 5 to 6 minutes, shaking the pot. Discard any that stay closed.', 'Finish with parsley and serve with bread for the broth.']),
  (41, 'Chicken Souvlaki', 'Greek', 'chicken', 35, 2, array['fresh'], false, 'A marinade of lemon, oregano and olive oil tenderizes the chicken in as little as 20 minutes.', array['500g chicken thighs, cubed', '2 lemons', '3 garlic cloves', '2 tsp dried oregano', 'Olive oil', 'Pita', 'Tzatziki', 'Tomato and red onion'], array['Marinate the chicken in lemon juice, oil, garlic and oregano for at least 20 minutes.', 'Thread onto skewers and grill or sear 10 minutes, turning, until charred.', 'Serve in pita with tzatziki, tomato and onion.']),
  (42, 'Classic Greek Salad', 'Greek', 'veg', 10, 1, array['fresh', 'quick'], true, 'Cutting the vegetables into large chunks and dressing just before serving keeps everything crisp.', array['4 tomatoes', '1 cucumber', '1 red onion', '1 cup Kalamata olives', '200g feta', 'Olive oil', 'Red wine vinegar', 'Dried oregano'], array['Cut the tomatoes, cucumber and onion into large chunks and combine with the olives.', 'Whisk oil, vinegar and oregano and dress the salad.', 'Top with a slab of feta and a pinch more oregano.']),
  (43, 'Shrimp Saganaki', 'Greek', 'seafood', 25, 2, array['cozy', 'fresh'], false, 'Feta melts into the tomato sauce, and the shrimp finish cooking in it in just a few minutes.', array['400g shrimp', '1 can chopped tomatoes', '1 onion', '2 garlic cloves', '100g feta', 'Parsley', 'Crusty bread'], array['Soften the onion and garlic in olive oil, add the tomatoes and simmer 10 minutes.', 'Add the shrimp and cook 3 minutes until pink.', 'Crumble the feta over the top, warm until soft, and finish with parsley.']),
  (44, 'Keftedes Meatball Bowls', 'Greek', 'beef', 40, 2, array['comfort', 'cozy'], false, 'A bread-and-milk paste keeps the meatballs tender, and grated onion adds moisture without chunks.', array['500g ground beef or lamb', '1 slice bread soaked in milk', '1 egg', '1 onion, grated', 'Dried mint and oregano', 'Cooked rice', 'Tzatziki'], array['Mix the beef with the soaked bread, egg, onion, herbs and salt. Roll into small balls.', 'Bake at 220°C for 15 minutes, turning once, until browned.', 'Serve over rice with tzatziki.']),
  (45, 'Lemongrass Chicken Banh Mi', 'Vietnamese', 'chicken', 40, 2, array['fresh'], false, 'Quick-pickled carrots and cucumber cut through the rich chicken and add crunch.', array['500g chicken thighs', '2 lemongrass stalks, minced', '2 tbsp fish sauce', '1 tbsp sugar', 'Baguettes', 'Carrot, pickled', 'Cucumber', 'Cilantro', 'Mayonnaise'], array['Marinate the chicken in lemongrass, fish sauce and sugar for at least 15 minutes.', 'Sear or grill 6 minutes per side until charred. Slice.', 'Fill toasted baguettes with mayo, chicken, pickles, cucumber and cilantro.']),
  (46, 'Shrimp Summer Rolls', 'Vietnamese', 'seafood', 30, 2, array['fresh', 'quick'], false, 'Soaking rice paper for only a few seconds lets it finish softening as you roll, so it does not tear.', array['12 rice paper wrappers', '300g cooked shrimp, halved', 'Rice vermicelli', 'Lettuce', 'Mint', 'Cucumber and carrot, cut into strips', 'Peanut sauce'], array['Cook the vermicelli, rinse, and prep every filling within reach.', 'Dip a wrapper in warm water for 5 seconds and lay it flat. Add shrimp, vermicelli, herbs and vegetables.', 'Fold in the sides and roll tightly. Serve with peanut sauce.']),
  (47, 'Weeknight Beef Pho', 'Vietnamese', 'beef', 40, 2, array['cozy', 'comfort'], false, 'Charring the onion and ginger first gives a fast broth the depth of a long-simmered one.', array['6 cups beef stock', '1 onion, halved', '3-inch ginger', '2 star anise', '1 cinnamon stick', '2 tbsp fish sauce', '200g thinly sliced sirloin', 'Rice noodles', 'Bean sprouts, basil, lime'], array['Char the onion and ginger under the broiler or in a dry pan until blackened in spots.', 'Simmer with the stock, star anise, cinnamon and fish sauce for 25 minutes; strain.', 'Pour the boiling broth over noodles and raw beef slices in bowls; add sprouts, basil and lime.']),
  (48, 'Tofu Vermicelli Bowls', 'Vietnamese', 'tofu', 30, 1, array['fresh'], true, 'Pan-frying the tofu until golden gives it a crisp edge that stands up to the dressing.', array['1 block firm tofu, cubed', 'Rice vermicelli', 'Lettuce', 'Cucumber', 'Mint and cilantro', 'Pickled carrot', '2 tbsp soy sauce', '2 tbsp lime juice', '1 tbsp sugar', 'Roasted peanuts'], array['Pan-fry the tofu in oil until golden on all sides.', 'Whisk soy sauce, lime juice, sugar and a splash of water for the dressing.', 'Layer noodles, greens, herbs and vegetables in bowls; top with tofu, peanuts and dressing.'])
